uiState.selectedEntity = null;
uiState.selectedEntityName = "";
uiState.detailsList = [];
if (Object.hasOwn(uiState, 'isFormOpen')) {
    uiState.isFormOpen = false;
}

if (Object.hasOwn(uiState, 'isAdding')) {
    uiState.isAdding = false;
}

if (Object.hasOwn(uiState, 'isEditing')) {
    uiState.isEditing = false;
}

if (Object.hasOwn(uiState, 'isCreatingNewEntity')) {
    uiState.isCreatingNewEntity = false;
}

if (Object.hasOwn(uiState, 'isEditingExistingEntity')) {
    uiState.isEditingExistingEntity = false;
}

const {
    uiState,          // The page's UI state object
    utils,            // The Utils service
    referenceService, // The ReferenceDataService
    viewService,      // The EntityViewService
    gridData,         // The array of data for the grid (to handle revert)
    config            // Page specific config (mappers, exclusions)
} = options;

const tableCtrl = angular.element(document.querySelector('bln-table')).isolateScope().$ctrl;
const targetId = uiState.selectedEntity?.Id ?? row.Id;
const oldIndex = gridData.findIndex(r => r.Id === targetId);
const isEditing = uiState.isEditing || (uiState.isFormOpen && uiState.isEditingExistingEntity);
const isAdding = uiState.isAdding || (uiState.isFormOpen && uiState.isCreatingNewEntity);

const canSwitch = await viewService.checkUnsavedChanges(
    isEditing,
    uiState.selectedEntity?.Id,
    row?.Id,
    utils,
    isAdding,
);

if (!row) {
    if (isEditing) {
        if (!canSwitch) {
            utils.setSelectedBelliniTableRow(oldIndex);
            return;
        }
    }
    this.resetState(uiState);
    return;
}

if (Object.hasOwn(row, "Custom") && isEditing) {
    if (row.Custom === 0) {
        utils.toast("Cannot edit System Entities.", "INFO");
        utils.setSelectedBelliniTableRow(oldIndex);
        return;
    }
}

if (!canSwitch) {
    if (isAdding) {
        tableCtrl.gridApi.selection.clearSelectedRows();
    } else utils.setSelectedBelliniTableRow(oldIndex);
    return;
} else {
    if (isAdding) {
        const formKey = context.tabConfig[uiState.currentTab.name].form;
        if (Object.hasOwn(uiState, 'isAdding')) {
            uiState.isAdding = false;    
        }
        if (Object.hasOwn(uiState, 'isCreatingNewEntity')) {
            uiState.isCreatingNewEntity = false;
        }
        if (Object.hasOwn(uiState, 'isFormOpen')) {
            uiState.isFormOpen = false;
        }
        context.utils.resetForm(context[formKey]);
    }
}

uiState.isLoadingDetails = true;
uiState.detailsList = viewService.generateDetailsList(row, config);
uiState.selectedEntity = row;

const tabConfig = context.tabConfig[uiState.currentTab.name];
uiState.selectedEntityName = (typeof tabConfig.getName === "function") 
    ? tabConfig.getName(row) 
    : row[tabConfig.entityNameKey];

if (isEditing) {
    if (typeof context.handlers?.setInputValues === 'function') {
        context.handlers.setInputValues();
    } else {
        const formObj = context[tabConfig.form];
        context.formManagementService.populateFormForEdit(uiState, formObj);
    }
}

try {
    let fullEntity = row;
    if (options.hydrateFn) {
        fullEntity = await options.hydrateFn(row);
    } else if (referenceService) {
        fullEntity = await referenceService.hydrateEntity(row);
    }

    uiState.selectedEntity = fullEntity;

    uiState.detailsList = viewService.generateDetailsList(fullEntity, config);

    if (options.onFormInit && typeof options.onFormInit === 'function') {
        options.onFormInit(fullEntity);
    }

} catch (error) {
    console.error("BaseGridController: Selection Error", error);
    utils.toast("Failed to load details.", "ERROR");
} finally {
    uiState.isLoadingDetails = false;
    if (context.$timeout) context.$timeout(0);
}

const {
    entityType,
    customEntityKey,
    columnDefs,
    page = 1,
    limit = 25,
    query = "",
    hydrateOnLoad = false,
    resetUiState = true,
    touchLoadingStates = true,
    reloadColumns = false
} = options;

const store = context.tabStore[entityType];
if (!store) return;

// Create unique request ID for each call
// Attach it to each store so each tab tracks its own requests
store.currentRequestId = (store.currentRequestId ?? 0) + 1;
const currentRequestId = store.currentRequestId;

// Prepare the UI
if (touchLoadingStates) context.uiState.isLoadingTable = true;
if (resetUiState) this.resetState(context.uiState);

try {
    // Fetch Data
    const result = await context.payrollApiService.get({
        entity: entityType,
        page,
        limit,
        query,
        customEntityKey
    });

    // Abort if newer reequest was triggered
    if (store.currentRequestId !== currentRequestId) return; // Exit silently. Do not update data, do not touch the loader

    // Normalize Data
    const booleanKeys = context.utils.extractBooleanKeys(columnDefs);
    const cleanEntities = context.utils.normalizeBooleans(result.entities, booleanKeys);

    let finalData = cleanEntities;

    if (context.referenceDataService && context.referenceDataService.hydrateEntity && hydrateOnLoad) {
        finalData = await Promise.all(
            cleanEntities.map(entity => context.referenceDataService.hydrateEntity(entity))
        );


        // Await Promise.all takes time, so need to check again
        if (store.currentRequestId !== currentRequestId) return;
    }

    // Update Tab Store
    store.data = finalData;
    store.totalFiltered = result.metadata?.totalFiltered;
    store.totalCount = result.metadata?.totalCount;
    store.pageCount = (result.metadata?.pageCount && result.metadata?.pageCount > 0) ? result.metadata?.pageCount : 1;
    store.currentPage = result.metadata?.currentPage;
    store.hasNextPage = result.metadata?.hasNextPage;

    // Lazy-load Column Definitions
    if (!store.columns || store.columns.length === 0 || reloadColumns) {
        store.columns = context.utils.generateColumnDefinitions(columnDefs);
    }

    return finalData;
} catch (error) {
    // Only log errors and show toasts if this is still the active request
    if (store.currentRequestId === currentRequestId) {
        console.error(`[BaseGridController] Error loading ${entityType}`, error);
        context.utils.toast(`Failed to load ${entityType}`, "ERROR");
        throw error;
    }
} finally {
    // Prevent premature spinner hiding
    // Only turn off loading state if no newer reqest has taken over
    if (store.currentRequestId === currentRequestId && touchLoadingStates) {
        context.uiState.isLoadingTable = false;
    }
}
